// Generated by `npm run stamp`: a hash of every precached file. Any change to
// the app changes this line, which is what makes the browser install the new
// version. tests/sw-version.test.js fails when it is out of date.
const CACHE_NAME = 'trackit-3726f26acd';

const PRECACHE_URLS = [
    './',
    './index.html',
    './design-tokens.css',
    './fonts/archivo-latin.woff2',
    './fonts/archivo-latin-ext.woff2',
    './css/styles.css',
    './vendor/lucide.min.js',
    './vendor/ios-vibrator-pro-max.js',
    './vendor/web-haptics.js',
    './js/db.js',
    './js/utils.js',
    './js/copy.js',
    './js/exercises.js',
    './js/form-history.js',
    './js/rest-timer.js',
    './js/app.js',
    './js/components/icons.js',
    './js/components/header.js',
    './js/components/toast.js',
    './js/components/modal.js',
    './js/pages/home.js',
    './js/pages/history.js',
    './js/pages/workout-detail.js',
    './js/pages/create-workout.js',
    './js/pages/settings.js',
    './js/pages/exercise.js',
    './manifest.json',
    './icons/icon-192.png',
    './icons/icon-512.png'
];

// Install: download the complete new version, bypassing the HTTP cache
// (GitHub Pages lets browsers keep files for 10 minutes), then take over.
self.addEventListener('install', (e) => {
    e.waitUntil(
        caches.open(CACHE_NAME)
            .then(cache => cache.addAll(PRECACHE_URLS.map(url => new Request(url, { cache: 'reload' }))))
            .then(() => self.skipWaiting())
    );
});

// Activate: drop every older version, control open pages right away. The page
// reloads itself on `controllerchange` (see js/app.js).
self.addEventListener('activate', (e) => {
    e.waitUntil(
        caches.keys()
            .then(keys => Promise.all(keys.filter(key => key !== CACHE_NAME).map(key => caches.delete(key))))
            .then(() => self.clients.claim())
    );
});

// Fetch: serve the app only from the current version's cache. Every file
// comes from the same snapshot, so new and old files are never mixed; the
// cache is never written to after install. User data lives in IndexedDB and
// localStorage and is untouched by any of this.
self.addEventListener('fetch', (e) => {
    if (e.request.method !== 'GET') return;
    if (!e.request.url.startsWith(self.location.origin)) return;
    if (new URL(e.request.url).pathname.endsWith('/service-worker.js')) return;

    e.respondWith((async () => {
        const cache = await caches.open(CACHE_NAME);
        if (e.request.mode === 'navigate') {
            const page = await cache.match('./index.html');
            if (page) return page;
        }
        const cached = await cache.match(e.request, { ignoreSearch: true });
        if (cached) return cached;
        try {
            return await fetch(e.request);
        } catch (err) {
            const fallback = e.request.mode === 'navigate' ? await cache.match('./') : null;
            return fallback || Response.error();
        }
    })());
});
